1	package main
2	
3	import (
4		"bytes"
5		"strings"
6		"testing"
7	)
8	
9	// runReplicateExpectInputError 执行一次 replicate，断言整份输入在读取阶段被
10	// 拒绝：退出码 1、标准输出没有任何结果 JSON、标准错误带 replicate: 前缀且
11	// 指出字段的完整位置。
12	func runReplicateExpectInputError(t *testing.T, input, wantPath string) string {
13		t.Helper()
14		var stdout, stderr bytes.Buffer
15		code := runReplicateIO(strings.NewReader(input), &stdout, &stderr)
16		if code != 1 {
17			t.Fatalf("exit code = %d, want 1; stderr=%s", code, stderr.String())
18		}
19		if stdout.Len() != 0 {
20			t.Fatalf("no result JSON may be produced on a field type error, got: %s", stdout.String())
21		}
22		message := stderr.String()
23		if !strings.HasPrefix(message, "replicate:") {
24			t.Fatalf("error message missing replicate: prefix: %q", message)
25		}
26		if !strings.Contains(message, wantPath) {
27			t.Fatalf("error message must name the field location %q, got: %q", wantPath, message)
28		}
29		return message
30	}
31	
32	// 任务主场景：当前任期 2、初始日志含索引 1（任期 1）的条目，committedIndex
33	// 却显式写成 null。即使随后任期 3 的请求能从日志起点替换这条日志，也必须在
34	// 读取输入阶段失败——null 不能被解释成“尚未提交”而让初始日志失去提交保护。
35	func TestCLINullCommittedIndexRejectsWholeInput(t *testing.T) {
36		input := `{
37		  "currentTerm": 2,
38		  "committedIndex": null,
39		  "log": [{"index": 1, "term": 1, "command": "set x=1"}],
40		  "requests": [
41		    {"term": 3, "prevLogIndex": 0, "prevLogTerm": 0, "leaderCommit": 1,
42		     "entries": [{"index": 1, "term": 3, "command": "set x=2"}]}
43		  ]
44		}`
45		runReplicateExpectInputError(t, input, "committedIndex")
46	}
47	
48	// 前面的请求都合法、后面某条请求的 leaderCommit 为 null：同样拒绝整份输入，
49	// 不输出前面请求的部分结果，也不把它降为一次普通复制拒绝。
50	func TestCLINullLeaderCommitInLaterRequestRejectsWholeInput(t *testing.T) {
51		input := `{
52		  "currentTerm": 1,
53		  "committedIndex": 0,
54		  "log": [],
55		  "requests": [
56		    {"term": 1, "prevLogIndex": 0, "prevLogTerm": 0, "leaderCommit": 1,
57		     "entries": [{"index": 1, "term": 1, "command": "set a=1"}]},
58		    {"term": 1, "prevLogIndex": 1, "prevLogTerm": 1, "leaderCommit": null,
59		     "entries": [{"index": 2, "term": 1, "command": "set b=2"}]}
60		  ]
61		}`
62		runReplicateExpectInputError(t, input, "requests[1].leaderCommit")
63	}
64	
65	// 字段名只改变字母大小写时沿用同样的识别方式，不能绕过数值 null 校验。
66	func TestCLINullNumericFieldCaseVariantStillRejected(t *testing.T) {
67		input := `{
68		  "CurrentTerm": 1,
69		  "requests": [
70		    {"term": 1, "prevLogIndex": 0, "prevLogTerm": 0, "LeaderCommit": null,
71		     "entries": []}
72		  ]
73		}`
74		message := runReplicateExpectInputError(t, input, "requests[0].leaderCommit")
75		if strings.Contains(message, "LeaderCommit") && !strings.Contains(message, "leaderCommit") {
76			t.Fatalf("location should use the canonical field name, got: %q", message)
77		}
78	}
79	
80	// 初始状态与其余数值位置：currentTerm、初始日志条目的 index/term、请求的
81	// term/prevLogIndex/prevLogTerm，以及未提交条目的 index/term——都不能延迟
82	// 到提交时才判断。
83	func TestCLINullNumericFieldLocations(t *testing.T) {
84		cases := []struct {
85			name  string
86			input string
87			path  string
88		}{
89			{
90				name:  "initial currentTerm",
91				input: `{"currentTerm": null, "log": [], "requests": []}`,
92				path:  "currentTerm",
93			},
94			{
95				name:  "initial log entry index",
96				input: `{"currentTerm": 1, "log": [{"index": null, "term": 1, "command": "a"}]}`,
97				path:  "log[0].index",
98			},
99			{
100				name:  "initial log entry term",
101				input: `{"currentTerm": 1, "log": [{"index": 1, "term": null, "command": "a"}]}`,
102				path:  "log[0].term",
103			},
104			{
105				name: "request term",
106				input: `{"currentTerm": 1, "requests": [
107				  {"term": null, "prevLogIndex": 0, "prevLogTerm": 0, "leaderCommit": 0, "entries": []}
108				]}`,
109				path: "requests[0].term",
110			},
111			{
112				name: "request prevLogIndex",
113				input: `{"currentTerm": 1, "requests": [
114				  {"term": 1, "prevLogIndex": null, "prevLogTerm": 0, "leaderCommit": 0, "entries": []}
115				]}`,
116				path: "requests[0].prevLogIndex",
117			},
118			{
119				name: "request prevLogTerm",
120				input: `{"currentTerm": 1, "requests": [
121				  {"term": 1, "prevLogIndex": 0, "prevLogTerm": null, "leaderCommit": 0, "entries": []}
122				]}`,
123				path: "requests[0].prevLogTerm",
124			},
125			{
126				// 条目尚未提交：null 校验仍在读取输入阶段完成，不延迟到提交时。
127				name: "uncommitted entry index",
128				input: `{"currentTerm": 1, "requests": [
129				  {"term": 1, "prevLogIndex": 0, "prevLogTerm": 0, "leaderCommit": 0,
130				   "entries": [{"index": null, "term": 1, "command": "set a=1"}]}
131				]}`,
132				path: "requests[0].entries[0].index",
133			},
134			{
135				name: "uncommitted entry term",
136				input: `{"currentTerm": 1, "requests": [
137				  {"term": 1, "prevLogIndex": 0, "prevLogTerm": 0, "leaderCommit": 0,
138				   "entries": [{"index": 1, "term": null, "command": "set a=1"}]}
139				]}`,
140				path: "requests[0].entries[0].term",
141			},
142			{
143				name: "second entry of second request",
144				input: `{"currentTerm": 1, "requests": [
145				  {"term": 1, "prevLogIndex": 0, "prevLogTerm": 0, "leaderCommit": 0, "entries": []},
146				  {"term": 1, "prevLogIndex": 0, "prevLogTerm": 0, "leaderCommit": 0,
147				   "entries": [
148				     {"index": 1, "term": 1, "command": "a"},
149				     {"index": 2, "term": null, "command": "b"}
150				   ]}
151				]}`,
152				path: "requests[1].entries[1].term",
153			},
154		}
155		for _, tc := range cases {
156			t.Run(tc.name, func(t *testing.T) {
157				runReplicateExpectInputError(t, tc.input, tc.path)
158			})
159		}
160	}
161	
162	// 显式 null 与省略字段、合法数字 0 要区分开：省略仍采用默认值，{} 仍是合法
163	// 空初始状态，日志起点的索引 0 与任期 0 保持原有含义；数组字段与未知键里的
164	// null 沿用已有处理，不受数值校验影响。
165	func TestCLINullValidationKeepsExistingSemantics(t *testing.T) {
166		input := `{
167		  "currentTerm": 1,
168		  "committedIndex": 0,
169		  "log": null,
170		  "unknownKey": null,
171		  "requests": [
172		    {"term": 1, "prevLogIndex": 0, "prevLogTerm": 0, "leaderCommit": 0,
173		     "entries": null},
174		    {"term": 1, "prevLogIndex": 0, "prevLogTerm": 0, "leaderCommit": 1,
175		     "entries": [{"index": 1, "term": 1, "command": "set a=1"}]}
176		  ]
177		}`
178		var stdout, stderr bytes.Buffer
179		code := runReplicateIO(strings.NewReader(input), &stdout, &stderr)
180		if code != 0 {
181			t.Fatalf("exit code = %d, stderr=%s", code, stderr.String())
182		}
183		body := stdout.String()
184		for _, fragment := range []string{`"accepted": true`, `"finalCommittedIndex": 1`, `"set a=1"`} {
185			if !strings.Contains(body, fragment) {
186				t.Fatalf("output missing %s:\n%s", fragment, body)
187			}
188		}
189	}
